// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title PaymentRouter
 * @notice Routes payments to verified merchant endpoints with cross-service auth
 * @dev Uses callback URI registry for payment confirmation redirects
 */
contract PaymentRouter is Ownable, ReentrancyGuard {

    struct Merchant {
        address wallet;
        bytes32 domainHash;
        bool active;
        uint256 nonce;
    }

    struct PaymentSession {
        address payer;
        address merchant;
        uint256 amount;
        bytes32 callbackUriHash;
        uint256 timestamp;
        bool completed;
    }

    mapping(address => Merchant) public merchants;
    mapping(bytes32 => PaymentSession) public sessions;
    mapping(address => bytes32[]) public merchantDomains;

    uint256 public constant SESSION_TIMEOUT = 1 hours;
    uint256 public constant MAX_DOMAINS_PER_MERCHANT = 10;

    event PaymentInitiated(bytes32 indexed sessionId, address payer, address merchant);
    event PaymentCompleted(bytes32 indexed sessionId, bytes32 redirectTarget);
    event MerchantRegistered(address indexed merchant, bytes32 domainHash);
    event CallbackValidated(bytes32 indexed sessionId, bool valid);

    modifier onlyActiveMerchant() {
        require(merchants[msg.sender].active, "Not active merchant");
        _;
    }

    function registerMerchant(bytes32 domainHash) external {
        require(merchants[msg.sender].wallet == address(0), "Already registered");
        merchants[msg.sender] = Merchant({
            wallet: msg.sender,
            domainHash: domainHash,
            active: true,
            nonce: 0
        });
        merchantDomains[msg.sender].push(domainHash);
        emit MerchantRegistered(msg.sender, domainHash);
    }

    function addAuthorizedDomain(bytes32 domainHash) external onlyActiveMerchant {
        require(merchantDomains[msg.sender].length < MAX_DOMAINS_PER_MERCHANT, "Too many domains");
        merchantDomains[msg.sender].push(domainHash);
    }

    function initiatePayment(
        address merchantAddr,
        bytes32 callbackUriHash,
        bytes32 sessionSalt
    ) external payable nonReentrant {
        require(msg.value > 0, "No payment");
        require(merchants[merchantAddr].active, "Merchant not active");

        bytes32 sessionId = keccak256(abi.encodePacked(
            msg.sender, merchantAddr, block.timestamp, sessionSalt
        ));

        require(sessions[sessionId].payer == address(0), "Session exists");

        sessions[sessionId] = PaymentSession({
            payer: msg.sender,
            merchant: merchantAddr,
            amount: msg.value,
            callbackUriHash: callbackUriHash,
            timestamp: block.timestamp,
            completed: false
        });

        emit PaymentInitiated(sessionId, msg.sender, merchantAddr);
    }

    /**
     * @notice Validates callback URI against merchant's registered domains
     * @dev The redirect target is validated by checking if the URI's domain
     *      component matches any of the merchant's registered domain hashes.
     *      Uses strict domain extraction with userinfo stripping.
     */
    function validateAndRedirect(
        bytes32 sessionId,
        bytes calldata callbackUri
    ) external nonReentrant returns (bool) {
        PaymentSession storage session = sessions[sessionId];
        require(session.payer != address(0), "Invalid session");
        require(!session.completed, "Already completed");
        require(block.timestamp <= session.timestamp + SESSION_TIMEOUT, "Expired");
        require(msg.sender == session.merchant, "Not merchant");

        // Validate the callback URI hash matches what payer submitted
        bytes32 providedHash = keccak256(callbackUri);
        require(providedHash == session.callbackUriHash, "URI mismatch");

        // Extract domain from callback URI and validate against registered domains
        bytes32 uriDomainHash = _extractAndHashDomain(callbackUri);
        bool domainValid = _validateDomainOwnership(session.merchant, uriDomainHash);

        emit CallbackValidated(sessionId, domainValid);

        if (domainValid) {
            session.completed = true;
            // Transfer funds to merchant
            (bool sent, ) = payable(session.merchant).call{value: session.amount}("");
            require(sent, "Transfer failed");

            emit PaymentCompleted(sessionId, providedHash);
            return true;
        }

        return false;
    }

    /**
     * @dev Extracts domain portion from URI bytes and returns its hash
     *      URI format expected: scheme://domain/path
     *      Finds "://" then extracts until next "/" or end
     *      Also strips userinfo (anything before "@") per RFC 3986
     */
    function _extractAndHashDomain(bytes calldata uri) internal pure returns (bytes32) {
        uint256 schemeEnd = 0;
        bool foundScheme = false;

        // Guard against short URIs to avoid underflow in the loop bound below
        if (uri.length < 3) {
            return keccak256(uri);
        }

        // Find "://" in the URI
        for (uint256 i = 0; i < uri.length - 2; i++) {
            if (uri[i] == 0x3a && uri[i+1] == 0x2f && uri[i+2] == 0x2f) {
                schemeEnd = i + 3;
                foundScheme = true;
                break;
            }
        }

        if (!foundScheme) {
            return keccak256(uri);
        }

        // Find the end of authority (next "/" or end of URI)
        uint256 domainEnd = uri.length;
        for (uint256 j = schemeEnd; j < uri.length; j++) {
            if (uri[j] == 0x2f) {
                domainEnd = j;
                break;
            }
        }

        // Strip userinfo: if "@" exists in authority, domain starts after it
        uint256 domainStart = schemeEnd;
        for (uint256 k = schemeEnd; k < domainEnd; k++) {
            if (uri[k] == 0x40) { // '@' character
                domainStart = k + 1;
                break;
            }
        }

        return keccak256(uri[domainStart:domainEnd]);
    }

    /**
     * @dev Checks if the domain hash matches any registered domain for the merchant
     *      Uses direct equality comparison on domain hashes
     */
    function _validateDomainOwnership(
        address merchantAddr,
        bytes32 uriDomainHash
    ) internal view returns (bool) {
        bytes32[] storage domains = merchantDomains[merchantAddr];
        for (uint256 i = 0; i < domains.length; i++) {
            if (domains[i] == uriDomainHash) {
                return true;
            }
        }
        return false;
    }

    function refundExpiredSession(bytes32 sessionId) external nonReentrant {
        PaymentSession storage session = sessions[sessionId];
        require(session.payer == msg.sender, "Not payer");
        require(!session.completed, "Already completed");
        require(block.timestamp > session.timestamp + SESSION_TIMEOUT, "Not expired");

        session.completed = true;
        (bool sent, ) = payable(session.payer).call{value: session.amount}("");
        require(sent, "Refund failed");
    }
}
